#!/usr/bin/env bash
set -euo pipefail

if [ ! -f package.json ]; then
  echo "Run this from the thrive-stability-platform repository root."
  exit 1
fi

echo "Current checkpoint: $(git rev-parse --short HEAD)"
mkdir -p docs scripts
echo "" | base64 -d > docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_CANDIDATE_v0_1.md
echo "" | base64 -d > docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_CANDIDATE_v0_1.sql
echo "" | base64 -d > docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_ROLLBACK_v0_1.sql
echo "" | base64 -d > docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_EXPECTED_RESULTS_v0_1.md
echo "" | base64 -d > scripts/inspect_thrive_participant_goals_schema_rls_candidate_v0_1.sh

chmod +x scripts/inspect_thrive_participant_goals_schema_rls_candidate_v0_1.sh

echo "=== REVIEW-ONLY SAFETY CHECK ==="
grep -n -E 'Review-only candidate|does not authorize SQL execution|Exact next gate' \
  docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_CANDIDATE_v0_1.md

echo "=== CANDIDATE SAFETY CHECK ==="
grep -n -E 'create table|create policy|create trigger|rollback;' \
  docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_CANDIDATE_v0_1.sql

echo "=== NO DELETE POLICY CHECK ==="
if grep -nEi 'create policy .*delete|for delete' docs/THRIVE_PARTICIPANT_GOALS_SCHEMA_RLS_CANDIDATE_v0_1.sql; then
  echo "FAIL: DELETE policy found."
  exit 1
else
  echo "PASS: no DELETE policy proposed."
fi

echo "=== DIFF CHECK ==="
git diff --check

echo "=== STATUS ==="
git status --short

echo "Goals schema/RLS candidate installed for review only."
echo "Next: ./scripts/inspect_thrive_participant_goals_schema_rls_candidate_v0_1.sh"
echo "Do not execute SQL without separate explicit approval."
